package com.narudzbine.identity.application;
import com.narudzbine.identity.api.*;
import com.narudzbine.subscriptions.api.*;
import com.narudzbine.shared.api.ResourceRevisions;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.stereotype.Service;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
@Service
@ConditionalOnProperty(name={"identity.http.enabled","identity.setup.http.enabled"},havingValue="true")
public class PlanSessionService {
 private final JdbcTemplate jdbc;private final SessionService sessions;private final LoginThrottle throttle;private final VendorPlans plans;private final ResourceRevisions revisions;private final TransactionTemplate tx;
 public PlanSessionService(JdbcTemplate jdbc,SessionService sessions,LoginThrottle throttle,VendorPlans plans,ResourceRevisions revisions,PlatformTransactionManager manager){this.jdbc=jdbc;this.sessions=sessions;this.throttle=throttle;this.plans=plans;this.revisions=revisions;tx=new TransactionTemplate(manager);tx.setTimeout(10);}
 private UUID admit(String token,SessionTransport transport,boolean write){LoginThrottle.requireNoTransaction();UUID actor=tx.execute(s->sessions.authenticate(token,transport).accountId());throttle.admitApi(actor,write);return actor;}
 public VendorPlans.Page<VendorPlans.Plan> definitions(String token,SessionTransport transport,int page,int size,boolean retired,boolean total){admit(token,transport,false);return tx.execute(s->{sessions.authenticate(token,transport);var result=plans.plans(page,size,retired,total);sessions.recordSuccessfulActivity(token,transport);return result;});}
 public VendorPlans.Assignment current(String token,SessionTransport transport,UUID administrativeVendor){UUID actor=admit(token,transport,false);return tx.execute(s->{var principal=sessions.authenticate(token,transport);UUID vendor;if(administrativeVendor!=null){platform(principal);vendor=administrativeVendor;managedVendor(vendor);}else{vendor=vendor(actor,false);}var result=plans.current(vendor);sessions.recordSuccessfulActivity(token,transport);return result;});}
 public VendorPlans.Page<VendorPlans.Request> list(String token,SessionTransport transport,boolean admin,int page,int size,String state,boolean total){UUID actor=admit(token,transport,false);return tx.execute(s->{var principal=sessions.authenticate(token,transport);UUID vendor=null;if(admin){platform(principal);}else{vendor=vendor(actor,true);}var result=plans.requests(vendor,page,size,state,total);sessions.recordSuccessfulActivity(token,transport);return result;});}
 public VendorPlans.Request create(String token,SessionTransport transport,String csrf,UUID target){admit(token,transport,true);return tx.execute(s->{var principal=sessions.authenticateForOrganizationWrite(token,transport);csrf(token,transport,csrf);UUID vendor=vendor(principal.accountId(),true);var result=plans.create(principal.accountId(),vendor,target);sessions.recordSuccessfulActivity(token,transport);return result;});}
 public void withdraw(String token,SessionTransport transport,String csrf,UUID id,String expected){admit(token,transport,true);tx.executeWithoutResult(s->{var principal=sessions.authenticateForOrganizationWrite(token,transport);csrf(token,transport,csrf);UUID vendor=vendor(principal.accountId(),true);var r=plans.request(vendor,id);revision("planrequest/v1",id,r.revision(),expected);plans.withdraw(principal.accountId(),vendor,id);sessions.recordSuccessfulActivity(token,transport);});}
 public VendorPlans.Assignment assign(String token,SessionTransport transport,String csrf,UUID vendor,String expected,UUID target,String reason){admit(token,transport,true);tx.executeWithoutResult(s->platform(sessions.authenticate(token,transport)));return tx.execute(s->{var principal=sessions.authenticateForAdministrativeTradingWrite(token,transport,vendor,null);csrf(token,transport,csrf);managedVendor(vendor);var current=plans.current(vendor);revision("vendorplan/v1",vendor,current.revision(),expected);var result=plans.assign(principal.accountId(),vendor,target,reason,true);sessions.recordSuccessfulActivity(token,transport);return result;});}
 public VendorPlans.Request resolve(String token,SessionTransport transport,String csrf,UUID id,String expected,boolean approve,String reason){admit(token,transport,true);UUID vendor=tx.execute(s->{platform(sessions.authenticate(token,transport));return plans.request(null,id).vendorId();});return tx.execute(s->{var principal=sessions.authenticateForAdministrativeTradingWrite(token,transport,vendor,null);csrf(token,transport,csrf);managedVendor(vendor);var r=plans.request(vendor,id);revision("planrequest/v1",id,r.revision(),expected);var result=plans.resolve(principal.accountId(),vendor,id,approve,reason);sessions.recordSuccessfulActivity(token,transport);return result;});}
 private UUID vendor(UUID actor,boolean manage){var rows=jdbc.queryForList("SELECT b.organization_id,b.role FROM business_account b JOIN organization o ON o.id=b.organization_id WHERE b.id=? AND o.type='VENDOR' AND o.state='ACTIVE'",actor);if(rows.isEmpty()){throw fail(SetupFailure.Reason.NOT_FOUND);}if(manage&&!Set.of("OWNER","ADMIN").contains(rows.getFirst().get("role"))){throw fail(SetupFailure.Reason.FORBIDDEN);}return (UUID)rows.getFirst().get("organization_id");}
 private void managedVendor(UUID vendor){if(jdbc.queryForObject("SELECT count(*) FROM organization WHERE id=? AND type='VENDOR' AND state IN ('ACTIVE','SUSPENDED')",Integer.class,vendor)!=1){throw fail(SetupFailure.Reason.NOT_FOUND);}}
 private void revision(String domain,UUID id,long value,String expected){if(!revisions.matches(domain,id,value,expected)){throw new RevisionConflict(revisions.encode(domain,id,value));}}
 private void csrf(String token,SessionTransport transport,String csrf){if(transport==SessionTransport.BROWSER){sessions.requireCsrf(token,csrf);}}
 private static void platform(AuthenticatedSession session){if(!session.platformAdministrator()){throw fail(SetupFailure.Reason.FORBIDDEN);}}
 private static SetupFailure fail(SetupFailure.Reason r){return new SetupFailure(r);}
}
